        left_w = divider
        out = [[4] * left_w for _ in range(h)]
        for r, row in enumerate(grid):
            for c in range(left_w):
                right_c = divider + 1 + c
                if right_c < len(row) and row[right_c] == 4:
                    out[r][c] = 3
        return out

    # Smaller demo: return the left area as blank 4s.
    split_col = next(c for c in range(w) if all(row[c] == 7 for row in grid))
    return [[4] * split_col for _ in grid]

